_⚠️ Potential issue_ | _🟠 Major_ | _⚡ Quick win_

**Enforce a required fixed `schema_version` in event validation.**

`validate()` currently accepts events with a missing or arbitrary `schema_version` when callers construct/deserialize `ProductAnalyticsEvent` directly instead of using `new()`. That weakens schema compatibility guarantees.



<details>
<summary>Suggested fix</summary>

```diff
 pub(crate) fn validate(&self) -> Result<()> {
     let event_name = self.name.as_str();
     if event_name.is_empty() {
         return Err(analytics_error("event name must not be empty"));
     }

     let mut keys = HashSet::new();
+    let mut schema_version: Option<f64> = None;
     for prop in &self.string_props {
         validate_prop_key(self.name, &prop.key)?;
         validate_string_prop_value(&prop.key, &prop.value)?;
         if !keys.insert(prop.key.as_str()) {
             return Err(analytics_error("duplicate analytics prop key"));
@@
     for prop in &self.number_props {
         validate_prop_key(self.name, &prop.key)?;
         if !prop.value.is_finite() {
             return Err(analytics_error("analytics number prop must be finite"));
         }
+        if prop.key == "schema_version" {
+            schema_version = Some(prop.value);
+        }
         if !keys.insert(prop.key.as_str()) {
             return Err(analytics_error("duplicate analytics prop key"));
         }
     }
+
+    let expected = f64::from(PRODUCT_ANALYTICS_SCHEMA_VERSION);
+    match schema_version {
+        Some(v) if (v - expected).abs() <= f64::EPSILON => {}
+        Some(_) => return Err(analytics_error("analytics schema_version is invalid")),
+        None => return Err(analytics_error("analytics schema_version is required")),
+    }

     Ok(())
 }
```
</details>


